using Microsoft.EntityFrameworkCore; using Rajavasantha.Api.Domain;
namespace Rajavasantha.Api.Infrastructure;
public interface IRepository<T> where T:Entity { Task<T?> GetAsync(Guid id,CancellationToken ct=default); Task<IReadOnlyList<T>> ListAsync(CancellationToken ct=default); Task AddAsync(T entity,CancellationToken ct=default); void Remove(T entity); Task<int> SaveAsync(CancellationToken ct=default); }
public sealed class EfRepository<T>(AppDbContext db):IRepository<T> where T:Entity { readonly DbSet<T> set=db.Set<T>(); public Task<T?> GetAsync(Guid id,CancellationToken ct=default)=>set.SingleOrDefaultAsync(x=>x.Id==id,ct); public async Task<IReadOnlyList<T>> ListAsync(CancellationToken ct=default)=>await set.AsNoTracking().OrderByDescending(x=>x.CreatedAt).ToListAsync(ct); public Task AddAsync(T entity,CancellationToken ct=default)=>set.AddAsync(entity,ct).AsTask(); public void Remove(T entity){entity.IsDeleted=true;entity.UpdatedAt=DateTimeOffset.UtcNow;} public Task<int> SaveAsync(CancellationToken ct=default)=>db.SaveChangesAsync(ct); }
